footprint=dict(snapshot='838b4150303ca8228e8edb432d8b8ccae353d258',corpus_records_indexed=3646304,corpus_tables_complete=13,corpus_time_min='2025-04-02T17:45:08.318000Z',corpus_time_max='2026-09-19T00:03:19.890476Z',metadata_query_calls=len(log),retained_query_calls=len(valid),discarded_query_calls=len(log)-len(valid),query_methods=dict(Counter(x['method'] for x in valid)),bounded_record_appearances=appearances,unique_returned_records=len(records),unique_behavior_records=len([k for k in records if not k.startswith(('agents:','village_goals:'))]),clipped_excerpt_appearances=clipped,clipped_response_pages=sum(x.get('truncated',False) for x in valid),essential_anchors_reviewed=24,essential_anchors_hash_and_quote_verified=24,additional_raw_inspection_rows=len(raw),unique_raw_verified_rows=len(set(all_anchors)|{x['id'] for x in raw if x['hash_verified']}),quarter_strata=[x for x in valid if x['label'].startswith('blocked-')],definitions={'returned':'Retrieved bounded API records; not all source text read. Screened excerpts are not exhaustive review.','reviewed':'24 selected essential rows individually inspected in raw JSON with exact quote and hash verification.','stratification':'Six contiguous quarter windows span corpus timestamp extent; each chat blocked query takes newest four matches only.','incidence':'No estimated prevalence or exhaustive absence claims.','raw':'Individual authenticated raw JSON rows only; no source gzip files downloaded.'})
